// Variadic function that sums integers
int sum(int count, ...) {
    int total = 0;
    va_list args;
    va_start(args, count);              // initialise with the last fixed argument
    for (int i = 0; i < count; ++i)
        total += va_arg(args, int);     // next argument (of type int)
    va_end(args);                       // clean up
    return total;
}

int main() {
    std::cout << "Sum: " << sum(3, 10, 20, 30) << std::endl;   // Sum: 60
    return 0;
}

