#include <cstring>
using namespace std;

class Santa {                       // std::string member: default copy is safe
    string name;
public:
    Santa(string _name) : name(_name) {}
    void SetData(string _name) { name = _name; }
    void ShowData() { cout << name << endl; }
};

class Panda {                       // raw pointer + default copy = shallow copy (BUG)
    char* name;
public:
    Panda(const char* _name) { name = new char[30]; strcpy(name, _name); }
    void SetData(const char* _name) { strcpy(name, _name); }
    void ShowData() { cout << name << endl; }
    // no destructor / copy: Panda P2 = P1 shares the same buffer
};

class Bhalu {                       // deep copy
    char* name;
public:
    Bhalu(const char* _name) { name = new char[30]; strcpy(name, _name); }
    Bhalu(const Bhalu& other) {
        cout << "In Copy Constructor" << endl;
        name = new char[30];
        strcpy(name, other.name);
    }
    Bhalu& operator=(const Bhalu& other) {
        if (this != &other) {
            cout << "In Assignment operator" << endl;
            strcpy(name, other.name);
        }
        return *this;
    }
    ~Bhalu() { delete[] name; }
    void SetData(const char* _name) { strcpy(name, _name); }
    void ShowData() { cout << name << endl; }
};

int main() {
    {
        cout << "------------------std::string member------------------" << endl;
        Santa S1("Santa");
        Santa S2 = S1;
        S1.SetData("ShareMarket");
        S1.ShowData();                  // ShareMarket
        S2.ShowData();                  // Santa
    }
    {
        cout << "------------------Problem with shallow copy------------------" << endl;
        Panda P1("Panda");
        Panda P2 = P1;                  // pointer copied, buffer shared
        P1.SetData("House");
        P1.ShowData();                  // House
        P2.ShowData();                  // House (ideally "Panda")
    }
    {
        cout << "------------------Deep copy------------------" << endl;
        Bhalu B1("Bhalu");
        Bhalu B2 = B1;                  // In Copy Constructor
        B1.SetData("Google");
        B1.ShowData();                  // Google
        B2.ShowData();                  // Bhalu
        B2 = B1;                        // In Assignment operator
        B1.SetData("Little Bhalu");
        B1.ShowData();                  // Little Bhalu
        B2.ShowData();                  // Google (without an assignment operator it would share memory)
    }
    return 0;
}

#include <iostream>

class Array {
private:
    int* ptr;
    int size;
public:
    Array(int n) : ptr(new int[n]()), size(n) {}
    Array(const Array& obj) {
        ptr = new int[obj.size];             // allocate new space
        size = obj.size;
        for (int i = 0; i < obj.size; ++i)   // copy values
            ptr[i] = obj.ptr[i];
    }
    ~Array() { delete[] ptr; }
};

int main() {
    Array a(5);
    Array b = a;     // deep copy
}

class Array {
private:
    int* ptr;
    int size;
public:
    Array(int n = 0) : ptr(new int[n]()), size(n) {}
    Array(const Array& o) : ptr(new int[o.size]), size(o.size) {
        for (int i = 0; i < size; ++i) ptr[i] = o.ptr[i];
    }
    ~Array() { delete[] ptr; }
    Array& operator=(const Array& rhs);
};

Array& Array::operator=(const Array& rhs) {
    /* SELF ASSIGNMENT CHECK */
    if (this != &rhs) {
        delete[] ptr;                 // deallocate old memory
        ptr = new int[rhs.size];      // allocate new space
        size = rhs.size;
        for (int i = 0; i < size; i++)  // copy values
            ptr[i] = rhs.ptr[i];
    }
    return *this;
}

int main() {
    Array a(3), b(5);
    b = a;
}

