namespace A::B::C { int value = 1; }              // nested namespaces

template <typename T>
auto describe(T x) {
    if constexpr (std::is_integral_v<T>) return x + 1;   // compile-time branch
    else return x;
}

template <typename... Args>
auto sum(Args... args) { return (args + ...); }   // fold expression

int main() {
    std::map<std::string, int> m{{"a", 1}};
    if (auto it = m.find("a"); it != m.end())      // variable in if
        std::cout << it->second << std::endl;

    auto [k, v] = *m.begin();                      // structured bindings
    std::cout << k << v << " " << A::B::C::value << " "
              << describe(1) << " " << sum(1, 2, 3) << std::endl;
}

